function receipt = generate_route_a_vft_isrj_token_source_v2(executeGeneration)
% Fresh 63x80 source data for frozen token identifiability only.
if nargin<1; executeGeneration=false; end
projectRoot=fileparts(fileparts(mfilename('fullpath'))); generatorRoot='C:\LJQ_code\干扰数据\干扰信号生成程序\可配置组合干扰数据生成'; outputRoot='C:\LJQ_code\干扰数据\复合干扰数据0802_vft_isrj_token_source_v2'; auditRoot=fullfile(projectRoot,'outputs','tapc','route_a_vft_isrj_token_source_v2_generation'); addpath(generatorRoot,fullfile(generatorRoot,'core'),fullfile(generatorRoot,'generators'));
cfg=create_closedset_6class_config(); cfg.seed=181000000; cfg.output_dir=outputRoot; cfg.output.save_legacy=false; cfg.dataset.samples_per_pattern=80; cfg.dataset.num_samples=5040; cfg=normalize_and_validate_config(cfg,'balanced'); registry=build_jamming_registry(cfg); schema=build_parameter_schema(registry); result=run_closedset_splits(cfg,registry,schema,logical(executeGeneration),'train','error');
receipt=struct('status','completed','executed',logical(executeGeneration),'experiment','RouteA_VFTISRJ_TokenSourceV2','evidence_role','fresh_frozen_token_identifiability','base_seed',181000000,'sample_count',5040,'samples_per_pattern',80,'split_selection','train_only','test_split_generated',false,'locked_test_used',false,'test_v2_used',false,'test_v3_used',false); if executeGeneration; receipt.train_path=result.train_path; receipt.train_status=result.splits.train.status; end
if ~isfolder(auditRoot);mkdir(auditRoot);end; prefix='dry_run';if executeGeneration;prefix='formal';end;fid=fopen(fullfile(auditRoot,[prefix '_generation_receipt.json']),'w','n','UTF-8');cleaner=onCleanup(@()fclose(fid));fwrite(fid,jsonencode(receipt,PrettyPrint=true),'char');fprintf('ROUTE_A_TOKEN_SOURCE_V2_RECEIPT=%s\n',fullfile(auditRoot,[prefix '_generation_receipt.json']));
end
